"use strict";

const assert = require("node:assert/strict");
const crypto = require("node:crypto");
const fs = require("node:fs");
const os = require("node:os");
const path = require("node:path");
const test = require("node:test");
const { readQoderCnCliCredentials, normalizeQoderCnCliUsage } = require("../src/lib/qoder-cn-cli-limits");
const { fetchQoderCnLimits, normalizeQoderRpcUsage, readQoderLimitsCache } = require("../src/lib/qoder-limits");

// Generated by credential_storage_encrypt in the official @qodercn-ai/qoderclicn
// 1.1.68 WASM, then independently round-tripped with credential_storage_decrypt.
const GOLDEN_CREDENTIAL = "XDJtbBc/BECK0yCZoW72w72z/e80mYtoQDv7L/j2/nFKsj3tv9Wk6ovaNDQ8qBuFpFPmsUX+U12EzOtn3QkK0g==";
const MACHINE_ID = "fixture-machine-extra";

function fixtureHome(t, user) {
  const home = fs.mkdtempSync(path.join(os.tmpdir(), "tokentracker-qoder-cn-cli-"));
  t.after(() => fs.rmSync(home, { recursive: true, force: true }));
  const auth = path.join(home, ".qoder-cn", ".auth");
  fs.mkdirSync(auth, { recursive: true });
  fs.writeFileSync(path.join(auth, "machine_id"), `${MACHINE_ID}\n`);
  let encrypted = GOLDEN_CREDENTIAL;
  if (user) {
    const key = Buffer.from(MACHINE_ID.slice(0, 16));
    const cipher = crypto.createCipheriv("aes-128-cbc", key, key);
    encrypted = Buffer.concat([cipher.update(JSON.stringify(user)), cipher.final()]).toString("base64");
  }
  fs.writeFileSync(path.join(auth, "user"), encrypted);
  return home;
}

const USAGE = {
  user_id: "fixture", user_type: "personal_pro", expires_at: "2026-12-01T00:00:00Z",
  user_quota: { total: 100, used: 25, remaining: 75, percentage: 0.25, unit: "credits" },
  total_usage_percentage: 0.25, is_quota_exceeded: false,
};
const unavailableRpc = async () => { throw new Error("local service unavailable"); };
const response = (value) => ({ ok: true, status: 200, json: async () => value });

test("CN CLI credentials match the official WASM golden ciphertext", async (t) => {
  const home = fixtureHome(t);
  assert.deepEqual(await readQoderCnCliCredentials({ home, env: {} }), {
    token: "fixture-secret", organizationId: null,
  });
  const custom = path.join(home, "custom-cn");
  fs.renameSync(path.join(home, ".qoder-cn"), custom);
  assert.deepEqual(await readQoderCnCliCredentials({ home, env: {
    QODERCN_CONFIG_DIR: custom, QODER_CONFIG_DIR: "/international-must-not-be-read",
  } }), { token: "fixture-secret", organizationId: null });
});

test("CN CLI reads live quota without desktop IPC and caches only quota metadata", async (t) => {
  const home = fixtureHome(t);
  const result = await fetchQoderCnLimits({ home, env: {}, rpcRequest: unavailableRpc,
    fetchImpl: async (url, options) => {
      assert.equal(url, "https://openapi.qoder.com.cn/api/v2/quota/usage");
      assert.equal(options.headers.Authorization, "Bearer fixture-secret");
      assert.equal(options.redirect, "error");
      return response(USAGE);
    },
  });
  assert.equal(result.source, "cli-api");
  assert.equal(result.primary_window.used_percent, 25);
  assert.equal(result.plan_label, "personal_pro");
  assert.doesNotMatch(JSON.stringify(result), /fixture-secret/);
  const cachePath = path.join(home, ".tokentracker", "tracker", "qoder-cn-usage-limits-cache.json");
  assert.doesNotMatch(fs.readFileSync(cachePath, "utf8"), /fixture-secret/);
  assert.equal(readQoderLimitsCache({ home }), null);
});

test("CN CLI PAT takes precedence over disk credentials and never uses the international PAT", async (t) => {
  const home = fixtureHome(t);
  const calls = [];
  const result = await fetchQoderCnLimits({ home, env: {
    QODERCN_PERSONAL_ACCESS_TOKEN: "fixture-cn-pat", QODER_PERSONAL_ACCESS_TOKEN: "international-secret",
  }, rpcRequest: unavailableRpc, fetchImpl: async (url, options) => {
    calls.push(url);
    if (url.endsWith("/jobToken/exchange")) {
      assert.deepEqual(JSON.parse(options.body), { personal_token: "fixture-cn-pat" });
      return response({ token: "exchanged-token" });
    }
    assert.equal(options.headers.Authorization, "Bearer exchanged-token");
    return response(USAGE);
  } });
  assert.equal(calls.length, 2);
  assert.equal(result.primary_window.remaining_credits, 75);
  assert.doesNotMatch(JSON.stringify(result), /fixture-cn-pat|exchanged-token|international-secret/);
});

test("CN CLI organization credentials use the usage presentation API", async (t) => {
  const home = fixtureHome(t, { access_token: "organization-secret", organization_id: "fixture-org" });
  const result = await fetchQoderCnLimits({ home, env: {}, rpcRequest: unavailableRpc,
    fetchImpl: async (url) => {
      assert.equal(url, "https://openapi.qoder.com.cn/sash/api/v2/me/usage");
      return response({ displayMode: "qoder", qoderUsage: {
        userType: "personal_pro", userQuota: { used: 25, total: 100, percentage: 0.25 },
      } });
    },
  });
  assert.equal(result.primary_window.used_percent, 25);
});

test("CN CLI keeps add-on credits separate from plan credits for both API shapes", async (t) => {
  // Field names and separate bucket semantics come from the official
  // @qodercn-ai/qoderclicn 1.1.71 normalizer and /usage view; amounts are fixtures.
  const home = fixtureHome(t);
  for (const payload of [
    { ...USAGE, total_usage_percentage: 0.1, add_on_quota: { total: 500, used: 35, remaining: 465, percentage: 0.07 } },
    { displayMode: "qoder", qoderUsage: { userType: "personal_pro", userQuota: USAGE.user_quota,
      addOnQuota: { total: 500, used: 35, remaining: 465, percentage: 0.07 } } },
  ]) {
    const result = await fetchQoderCnLimits({ home, env: {}, rpcRequest: unavailableRpc,
      fetchImpl: async () => response(payload) });
    assert.equal(result.primary_window.limit_credits, 100);
    assert.equal(result.primary_window.used_credits, 25);
    assert.equal(result.primary_window.used_percent, 25);
    assert.equal(result.tertiary_window.limit_credits, 500);
    assert.equal(result.tertiary_window.used_credits, 35);
    assert.equal(result.tertiary_window.remaining_credits, 465);
    assert.ok(Math.abs(result.tertiary_window.used_percent - 7) < 1e-9);
    assert.equal(result.tertiary_window.reset_at, null);
    // Fresh TTL inherits the written cli-api source (#955); last-good still
    // preserves add-on credits when the live CLI call expires.
    const cached = await fetchQoderCnLimits({ home, env: {}, rpcRequest: unavailableRpc,
      fetchImpl: async () => ({ ok: false, status: 401 }) });
    assert.equal(cached.source, "cli-api");
    assert.equal(cached.stale, false);
    assert.deepEqual(cached.tertiary_window, result.tertiary_window);
  }
});

test("CN CLI handles absent, empty and standalone add-on quotas without inventing capacity", () => {
  const absent = normalizeQoderCnCliUsage(USAGE, normalizeQoderRpcUsage);
  assert.equal(absent.tertiary_window, undefined);
  const empty = normalizeQoderCnCliUsage({ ...USAGE,
    add_on_quota: { total: 0, used: 0, remaining: 0 } }, normalizeQoderRpcUsage);
  assert.equal(empty.tertiary_window.used_percent, 0);
  assert.equal(empty.tertiary_window.remaining_credits, 0);
  const standalone = normalizeQoderCnCliUsage({ add_on_quota: { total: 500, used: 35 } }, normalizeQoderRpcUsage);
  assert.equal(standalone.primary_window, null);
  assert.equal(standalone.tertiary_window.remaining_credits, 465);
  for (const add_on_quota of [{ total: null, used: 1 }, { total: 10, used: -1 }, { total: 0, used: 1 }, { total: 10, used: 1, remaining: "bad" }]) {
    assert.throws(() => normalizeQoderCnCliUsage({ ...USAGE, add_on_quota }, normalizeQoderRpcUsage), /add-on quota/);
  }
});

test("CN CLI rejects malformed quotas and ignores damaged encrypted credentials", async (t) => {
  assert.throws(() => normalizeQoderCnCliUsage({ user_quota: { total: null, used: 1 } }, normalizeQoderRpcUsage), /invalid quota/);
  assert.throws(() => normalizeQoderCnCliUsage({ user_quota: { total: 10, used: -1 } }, normalizeQoderRpcUsage), /invalid quota/);
  const home = fixtureHome(t);
  fs.writeFileSync(path.join(home, ".qoder-cn", ".auth", "user"), "corrupt");
  assert.equal(await readQoderCnCliCredentials({ home, env: {} }), null);
  const result = await fetchQoderCnLimits({ home, env: {}, rpcRequest: unavailableRpc,
    fetchImpl: async () => { assert.fail("no authenticated network call"); },
  });
  assert.equal(result.configured, false);
});

test("CN CLI unauthorized responses prompt reauthentication and preserve a bounded last-good cache", async (t) => {
  const home = fixtureHome(t);
  const options = { home, env: {}, rpcRequest: unavailableRpc };
  const expired = async () => ({ ok: false, status: 401 });
  const result = await fetchQoderCnLimits({ ...options, fetchImpl: expired });
  assert.equal(result.configured, true);
  assert.equal(result.auth_action_required, "reauth");
  assert.doesNotMatch(result.error, /fixture-secret/);
  await fetchQoderCnLimits({ ...options, fetchImpl: async () => response(USAGE) });
  // Within the fresh TTL the last-good re-serve keeps cli-api provenance
  // (#955) rather than forcing a degraded disk-cache/stale partial UI.
  const cached = await fetchQoderCnLimits({ ...options, fetchImpl: expired });
  assert.equal(cached.source, "cli-api");
  assert.equal(cached.stale, false);
  assert.equal(cached.primary_window.used_percent, 25);
});
